#include <iostream>
#include <string>

int main() {
    std::string data;
    std::getline(std::cin, data);
    char first_char = data[0];
    std::string rest_of_string = data.substr(1);
    size_t pos;
    while ((pos = rest_of_string.find("dot")) != std::string::npos) {
        rest_of_string.replace(pos, 3, ".");
    }
    std::string full_string = first_char + rest_of_string;
    if (!full_string.empty() && full_string.back() == '.') {
        full_string.back() = 't'; // temporarily replace '.' with 't'
        full_string += "dot"; // append 'dot' to the string
        full_string.pop_back(); // remove the 't' replaced earlier
        full_string.back() = '.'; // restore the last character to '.'
    }
    first_char = full_string[0];
    std::string rest_string = full_string.substr(1);
    size_t at_pos = rest_string.find("at");
    if (at_pos != std::string::npos) {
        rest_string.replace(at_pos, 2, "@");
    }
    if (!rest_string.empty() && rest_string.back() == '@') {
        rest_string.back() = 't'; // temporarily replace '@' with 't'
        rest_string += "at"; // append 'at'
        rest_string.pop_back(); // remove the 't' replaced earlier
        rest_string.back() = '@'; // restore '@'
    }
    std::cout << first_char + rest_string << std::endl;
    return 0;
}
